def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast counters over the whole match.
    opp_c = 0
    opp_d = 0
    my_d = 0
    for i in range(n):
        mine, opp = history[i]
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if mine == 'D':
            my_d += 1

    last_me, last_opp = history[-1]

    # Opponent has never defected: pure cooperator. Extract maximum value
    # while keeping them cooperating, then defect heavily at the very end.
    if opp_d == 0:
        if n >= 96:
            return 'D'
        if n >= 88 and rng.random() < 0.5:
            return 'D'
        if n >= 70 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # Recent window.
    w = 10 if n >= 10 else n
    start = n - w
    rec_c = 0
    rec_d = 0
    rec_my_d = 0
    for i in range(start, n):
        mine, opp = history[i]
        if opp == 'C':
            rec_c += 1
        else:
            rec_d += 1
        if mine == 'D':
            rec_my_d += 1

    # Clear exploiter: mostly defects recently and overall. Punish hard but
    # occasionally probe with C to catch a cooperating opponent.
    if rec_d * 3 >= w * 2 and opp_d * 3 >= n * 2:
        if last_opp == 'C' and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Pure defector.
    if opp_c == 0:
        if n >= 3 and rng.random() < 0.04:
            return 'C'
        return 'D'

    # If opponent has shown sustained recent cooperation, reward it strongly.
    if rec_d <= 1 and opp_d * 4 <= n:
        # Late-game exploitation against a reliable cooperator.
        if n >= 95:
            return 'D'
        if n >= 80 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Immediate response.
    if last_opp == 'D':
        # If we've already defected a lot and opponent is otherwise decent,
        # forgive once to break DD spirals.
        if last_me == 'D':
            if rec_my_d >= 3 and opp_d * 3 < n * 2:
                if rng.random() < 0.55:
                    return 'C'
            return 'D'
        # Opponent defected while we cooperated: retaliate with high prob,
        # but forgive if their overall behavior is good.
        if opp_d * 4 <= n and rng.random() < 0.35:
            return 'C'
        return 'D'

    # last_opp == 'C'.
    # If we've been defecting more than them, sometimes lock in cooperation.
    if rec_my_d >= 3 and rec_d <= 1:
        return 'C'

    # Periodic/recovering opponent: cooperate but probe occasionally.
    if n >= 3 and n < 95:
        probe = 0.0
        if opp_d * 3 <= n:
            probe = 0.03
        elif opp_d * 2 <= n:
            probe = 0.05
        else:
            probe = 0.08
        if rng.random() < probe:
            return 'D'
    elif n >= 95:
        # Endgame: exploit cooperators more aggressively.
        if rng.random() < 0.25:
            return 'D'

    return 'C'
